arguments.argument:
// ファイル読み直し
// file name list
ds_list_clear(fname_list);

//bkg_index_max = i;
bkg_index_max = load_image_names(fname_list);

global.cur_bkg_index = 0;
//background_index[0] = load_new_image(ds_list_find_value(fname_list, global.cur_bkg_index));
fname = ds_list_find_value(fname_list, global.cur_bkg_index)
background_index[0] = load_new_image(fname, touka);//background_add(fname, touka, false);

fit_window_size_to_image( background_index[0], 1 );
global.img_scale = 1.0;

// データベースにファイル名があれば、HipHoleを自動設定
fname = filename_name(string(fname));
if( ds_hh_findname(fname) != -1 ){
  global.hip_hole_x[global.cur_bkg_index] = real(ds_hh_getx(fname));
  global.hip_hole_y[global.cur_bkg_index] = real(ds_hh_gety(fname));
}

// ファイル名に[F8]があれば，自動的に透過モードにする．無かったらノーマルモードにする
if( ( string_count("[F8]", fname) >= 1 && !touka ) || ( string_count("[F8]", fname) == 0 && touka ) ){
    event_perform(ev_keypress, vk_f8);
}

// 表示位置をデフォルトに戻す
global.delta_x = 0;
global.delta_y = 0;
